import React from 'react';
import './timeline.css'; // Assure-toi de créer ce fichier CSS (voir plus bas)

const Timeline = () => {
  return (
    <div className="timeline-container">

      {/* --- 1. TRONC COMMUN (Haut) --- */}
      <div className="section trunk">
        <h3 className="section-title">PROJET REACT INITIAL<br/><span>(Tronc Commun)</span></h3>
        <Step label="Init Setup" />
        <Step label="Base Components" />
        <Step label="Core Logic" />
        {/* La ligne verticale centrale */}
        <div className="line-center"></div>
      </div>

      {/* --- 2. POINT DE DIVERGENCE (Milieu) --- */}
      <div className="divergence-point">
        <div className="node highlight-node"></div>
        <div className="label-highlight">
          <strong>POINT DE DIVERGENCE</strong><br/>
          (Choix Technique / Fork)
        </div>
      </div>

      {/* --- 3. LES BRANCHES (Bas) --- */}
      <div className="branches-container">

        {/* Branche Gauche (Timeline A) */}
        <div className="branch left-branch">
          <div className="branch-header">
            <h4>TIMELINE A</h4>
            <span>(Client-Side Features)</span>
          </div>
          {/* Ligne de branche */}
          <div className="line-branch"></div>

          <Step label="UI/UX" />
          <Step label="Animations" />
          <Step label="Mobile Opt." />
          <div className="arrow-down">▼</div>
        </div>

        {/* Branche Droite (Timeline B) */}
        <div className="branch right-branch">
          <div className="branch-header">
            <h4>TIMELINE B</h4>
            <span>(Server/Admin Focus)</span>
          </div>
           {/* Ligne de branche */}
           <div className="line-branch"></div>

          <Step label="API Integr." />
          <Step label="Dashboard" />
          <Step label="Auth System" />
          <div className="arrow-down">▼</div>
        </div>

      </div>
    </div>
  );
};

// Petit composant réutilisable pour chaque "point"
const Step = ({ label }) => (
  <div className="step">
    <div className="node"></div>
    <span className="step-label">{label}</span>
  </div>
);

export default Timeline;
